source='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    base = Counter(v for row in grid for v in row).most_common(1)[0][0]
    row_lines = [r for r, row in enumerate(grid) if sum(v != base for v in row) > w // 2]
    col_lines = [c for c in range(w) if sum(grid[r][c] != base for r in range(h)) > h // 2]
    nodes = [[grid[r][c] for c in col_lines] for r in row_lines]
    separator = Counter(v for row in nodes for v in row).most_common(1)[0][0]
    out = [[base for _ in range(len(col_lines)-1)] for _ in range(len(row_lines)-1)]
    for r in range(len(out)):
        for c in range(len(out[0])):
            corners = (nodes[r][c], nodes[r][c+1], nodes[r+1][c], nodes[r+1][c+1])
            if corners[0] == corners[1] == corners[2] == corners[3] and corners[0] != separator:
                out[r][c] = corners[0]
    while len(out) > 1 and all(v == base for v in out[0]): out.pop(0)
    while len(out) > 1 and all(v == base for v in out[-1]): out.pop()
    while len(out[0]) > 1 and all(row[0] == base for row in out):
        for row in out: row.pop(0)
    while len(out[0]) > 1 and all(row[-1] == base for row in out):
        for row in out: row.pop()
    return out
'''
